  var TD_SHORT = { callback: 'Hẹn gọi lại', d1: 'Hỏi nhận hàng', runout: 'Sắp hết hàng', d7: 'Hỏi thăm 1 tuần', d14: 'Xin cảm nhận', d30: 'Gợi ý sản phẩm', winback: 'Mời quay lại', old: 'Lâu chưa gọi' };
