    return '<button class="btn pri lg block" data-order="' + esc(x.o.id) + '">▶ Bắt đầu: ' + nm(x.o.name) + ' · ' + (x.k === 'order' ? 'xác nhận đơn' : 'gọi giữ đơn') + '</button>';
