    if (!list.length) return rs ? empty('Chưa có khách nào giới thiệu. Khi thêm khách hỏi, chọn “Khách giới thiệu” rồi chọn người giới thiệu.') : sq ? searchEmpty('khách đã mua', sq) : empty('Không có khách nào khớp.');
