  function ktKind(g) { var n = norm(g); return /quang cao|\bads\b/.test(n) ? 'ads' : /san tmdt|shopee|tiktok shop|lazada/.test(n) ? 'san' : ''; }
  /** 1 dòng → nhãn (các ô chữ trước số đầu tiên, bỏ STT / số La Mã) + các số sau nhãn. */
