    mj.days.forEach(function (r) { if (chInfo(r[1]).ret) return; M.ch[r[1]] = (M.ch[r[1]] || 0) + r[2]; M.tot += r[2]; M.day[r[0]] = (M.day[r[0]] || 0) + r[2]; });
    mj.prev.forEach(function (r) { if (chInfo(r[0]).ret) return; M.chp[r[0]] = r[1]; M.totp += r[1]; });
