        card(over ? 'bad' : 'ok', '⚠️ Quá hạn', moneyShort(over), over ? nOver + ' nhà cung cấp: trả ngay hoặc hẹn lại' : 'Không khoản nào quá hạn') +
        card(d7 ? 'mid' : 'ok', '📅 Tới hạn 7 ngày', moneyShort(d7), d7 ? 'chuẩn bị tiền' : 'Không khoản nào') + '</div>';
