      var st = a[1], mo = lgtMon(), L = lgtRows(mo), net = L.reduce(function (s, r) { return s + r.net; }, 0), w = L.filter(function (r) { return r.W.length; }).length, sum = L.length + ' người, thực lĩnh ' + moneyShort(net);
