        Object.keys(KTV_COL).forEach(function (k) { for (var j = 0; j < H.length; j++) if (KTV_COL[k].test(H[j])) { ix[k] = j; break; } });
        H.forEach(function (h, j) { if (/^(trang thai|tinh trang)$/.test(h)) sts.push(j); });
