        var hs = H.join('|'), carrier = /cod khach hang duoc nhan|co chieu tra ve hay khong/.test(hs) ? 'BEST Express' : /don chuyen hoan|bc goc|trang thai doi soat cod/.test(hs) ? 'Viettel Post' : '', L = [];
