  var IN_TABS = [['tong', '📊 Tổng quan'], ['tao', '✍️ Tạo nội dung'], ['cham', '🧪 Chấm bài'], ['loi', '🗣 Lời khách'], ['gac', '🛡 Gác cổng'], ['nhom', '👥 Nhóm khách'], ['cai', '⚙️ Cài đặt']];
