      $('#zbSendFile', m).onchange = function () { var f = this.files && this.files[0]; if (!f) return; shrinkImage(f).then(function (src) { simg = src; sdraw(); }, function () { toast('Không đọc được ảnh này, bạn chọn ảnh khác nhé.', true); }); };
