  var FP_LF = { all: ['Tất cả', null], need: ['🙋 Cần xử lý', ['handoff']], reply: ['💬 Trả lời khách', ['comment', 'dm', 'handoff']], lead: ['🎁 Xin số & quà', ['gift_ask', 'lead', 'nudge']], post: ['📝 Bài đăng', ['post']], err: ['⚠️ Lỗi', ['error', 'connect']] };
