      var sum = [[c2.comment, 'bình luận'], [c2.dm, 'tin nhắn'], [c2.lead, 'khách để số'], [c2.handoff, 'cần người thật'], [c2.post, 'bài'], [c2.error, 'lỗi']].filter(function (x) { return x[0]; }).map(function (x) { return x[0] + ' ' + x[1]; }).join(' · ');
