    return L.sort(function (a, b) { return a.p - b.p; }).slice(0, 5).map(function (x) { var w = whoOf(x.t); return (w ? '<span class="mk-who' + (w === 'Marketing' ? '' : ' s') + '">' + w + '</span> ' : '') + x.t; });
