    var redraw = function () { var c = cur(); tb = dailyTable(c[0], c[1]); $('#dyTbl', m).innerHTML = tb.html; $('#dyText', m).value = dailyText(c[0], c[1]); $('#dyList', m).innerHTML = dayOrdersHtml(c[0], c[1]); };
