      var mine = !c.owner || c.owner === S.user.name, zl = mine ? ((S.d.prefs || {}).zalo || '') : '', who = mine && zl ? S.user.name + ' ' + fPhone(zl) : 'Thực Dưỡng Lành ' + HOTLINE_TDL;
